Refactor this code by converting the namedtuple configuration to a dataclass:

from collections import namedtuple

Config = namedtuple('Config', ['host', 'port', 'debug'])

def make_config():
    import os
    return Config(os.environ.get('HOST', 'localhost'), int(os.environ.get('PORT', '8080')), os.environ.get('DEBUG') == '1')

output:
from dataclasses import dataclass
import os

@dataclass(frozen=True)
class Config:
    host: str = 'localhost'
    port: int = 8080
    debug: bool = False

def make_config():
    return Config(
        host=os.environ.get('HOST', 'localhost'),
        port=int(os.environ.get('PORT', '8080')),
        debug=os.environ.get('DEBUG') == '1',
    )

What changed: a positional namedtuple became a frozen dataclass with types, defaults and keyword construction, so fields can no longer be mis-ordered.

