Refactor this code by replacing the pkg_resources entry-point lookup with importlib.metadata:

from pkg_resources import load_entry_point

def get_version():
    return load_entry_point('myapp', 'myapp.version', 'get_version')()

def plugins():
    return [ep.name for ep in load_entry_point.iter_entry_points('myapp.plugins')]

output:
from importlib.metadata import entry_points, version

def get_version():
    return version('myapp')

def plugins():
    eps = entry_points(group='myapp.plugins')
    return [ep.name for ep in eps]

What changed: pkg_resources (slow to import, setuptools-dependent) was replaced by stdlib importlib.metadata, and version() replaced a roundabout entry point.

